from typing import List, Optional

def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None
    max_len = -1
    result = None
    for s in strings:
        current_len = len(s)
        if current_len > max_len:
            max_len = current_len
            result = s
    return result

