initial_code:
import math

def find_zero(xs: list):
    max_coeff = max(xs, key=lambda x: abs(x))
    index = xs.index(max_coeff)
    x = index / (index + 1)
    for _ in range(100):
        fx = sum(coeff * math.pow(x, i) for i, coeff in enumerate(xs))
        if abs(fx) < 1e-10:
            break
        dfx = sum(i * coeff * math.pow(x, i-1) for i, coeff in enumerate(xs))
        if dfx == 0:
            break
        x -= fx / dfx
    return round(x, 2)

