def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = []
    a, b = 1, 1
    while len(primes) < n:
        if is_prime(b):
            primes.append(b)
        a, b = b, a + b
    return primes[-1]

