def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest = 1
    # Handle the case for 2
    if n % 2 == 0:
        largest = 2
        while n % 2 == 0:
            n = n // 2
        if n == 1:
            return largest
    # Check odd factors starting from 3
    i = 3
    max_factor = int(n**0.5) + 1
    while i <= max_factor and n > 1:
        if n % i == 0:
            largest = i
            while n % i == 0:
                n = n // i
            if n == 1:
                return largest
            max_factor = int(n**0.5) + 1  # Update max_factor after division
        i += 2
    # If remaining n is a prime greater than 2
    return n if n > 1 else largest

