import math

def is_simple_power(x, n):
    """Returns True if x is a simple power of n, False otherwise."""
    if x == 0:
        return n == 0
    if n == 0:
        return False
    k = round(math.log(abs(x), abs(n)))
    if not math.isclose(x, n ** k):
        return False
    if x < 0:
        return n < 0 and k % 2 == 1
    return n > 0 and k % 2 == 0

initial_code:
def iscube(a):
    if a == 0:
        return True
    abs_a = abs(a)
    low = 0
    high = abs_a
    while low <= high:
        mid = (low + high) // 2
        cube = mid ** 3
        if cube == abs_a:
            return True
        elif cube < abs_a:
            low = mid + 1
        else:
            high = mid - 1
    return False

