import re

def anti_shuffle(s):
    tokens = re.findall(r'\S+|\s+', s)
    processed = []
    for token in tokens:
        if token.isspace():
            processed.append(token)
        else:
            sorted_token = ''.join(sorted(token, key=lambda x: ord(x)))
            processed.append(sorted_token)
    return ''.join(processed)

def get_row(lst, x):
    coordinates = []
    for i, row in enumerate(lst):
        for j, val in enumerate(row):
            if val == x:
                coordinates.append((i, j))
    coordinates.sort(key=lambda t: (t[0], -t[1]))
    return coordinates

def sort_array(array):
    arr = list(array)
    n = len(arr)
    if n <= 1:
        return arr
    sum_indices = 0 + (n - 1)
    if sum_indices % 2 == 1:
        return sorted(arr)
    else:
        return sorted(arr, reverse=True)

