initial_code:
import re

def valid_date(date):
    if not date:
        return False
    if not re.fullmatch(r'\d{2}-\d{2}-\d{4}', date):
        return False
    parts = date.split('-')
    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])

    if month < 1 or month > 12:
        return False
    if day < 1:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:  # February
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            max_day = 29
        else:
            max_day = 28

    return day <= max_day

