import heapq

def minPath(grid, k):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    heap = []
    best = {}

    # Initialize the heap with all possible starting positions
    for i in range(n):
        for j in range(n):
            path = (grid[i][j],)
            heapq.heappush(heap, (path, i, j, 1))
            best[(i, j, 1)] = path

    while heap:
        current_path, i, j, s = heapq.heappop(heap)
        # Check if current path is the k-length solution
        if s == k:
            return list(current_path)
        # Skip if a better path for this cell and step already exists
        if best.get((i, j, s), None) != current_path:
            continue
        # Explore all four possible directions
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < n:
                new_value = grid[ni][nj]
                new_path = current_path + (new_value,)
                new_s = s + 1
                # Check if this new path is better than existing for the next step
                key = (ni, nj, new_s)
                if key not in best or new_path < best[key]:
                    best[key] = new_path
                    heapq.heappush(heap, (new_path, ni, nj, new_s))

    # The problem states the answer exists, so this line is theoretically unreachable
    return []

