def specialFilter(nums):
    count = 0
    for num in nums:
        if num <= 10:
            continue
        abs_num = abs(num)
        temp = abs_num
        while temp >= 10:
            temp = temp // 10
        first_digit = temp
        last_digit = abs_num % 10
        if first_digit % 2 == 1 and last_digit % 2 == 1:
            count += 1
    return count

